{
    /** 同步保持已绑定来源；替换允许显式选择另一个来源。 */
    operation: 'replace' | 'synchronize';
    /** 同步已消失的字段或替换时明确选中的字段；保存前核验命令依赖。 */
    removals: Array<{
        id: string;
        name: string;
        type: string;
    }>;
    /** 来源已消失的普通字段可以显式选择移除，主键须同时校验候选合同。 */
    removalChoices: Array<{
        id: string;
        name: string;
        removed: boolean;
    }>;
    /** 新来源参数的明确取值；未配置时不得提交替换或同步。 */
    inputChoices: Array<{
        sourceName: string;
        value: string;
    }>;
    /** 当前已保存的空间参数目录；不可读时常量仍可编辑。 */
    inputParams: Array<{
        value: string;
        label: string;
    }>;
    /** 参数声明不可用的原因；不猜测引用。 */
    parameterWarning: string;
    /** 已有字段的类型/主键差异；只有明确确认才进入原视图变更。 */
    contractChanges: Array<{
        id: string;
        name: string;
        before: string;
        after: string;
        accepted: boolean;
        patch: Record<string, unknown>;
    }>;
    /** 与本次来源合同一起确认、在数据库回读后提交的命名视图变化。 */
    viewChanges: SourceContractPlan['viewChanges'];
    /** 保持不变的模型注册名。 */
    name: string;
    /** 精确重读得到的来源。 */
    prepared: Prepared;
    /** 逐字段兼容性结果，不包含运行行或权限凭据。 */
    differences: Array<{
        name: string;
        result: string;
    }>;
    /** 须先处理的迁移或诊断项。 */
    problems: string[];
    /** 原字段到同用途来源字段的显式选择；数据字段的合同差异另行确认。 */
    fieldChoices: Array<{
        id: string;
        name: string;
        outputName: string;
        sourceName: string;
        candidates: string[];
    }>;
    /** 尚未绑定的数据字段，可显式引入为输出列。 */
    additions: Array<{
        sourceName: string;
        included: boolean;
    }>;
    /** 原始关系表达式与按本次字段映射生成的提交值；只在确认时写入。 */
    relationChanges: Array<{
        id: string;
        before: string;
        after: string;
    }>;
    /** 模型自身来源字段引用的原值和显式映射结果；输出名称不参与迁移。 */
    modelChanges: Array<{
        property: string;
        before: string;
        after: string;
    }>;
    /** 自身和依赖模型Filter字段引用变更；后端Join配置不参与本轮迁移。 */
    expressionChanges: ReturnType<typeof LowcodeDataSpaceModelMigration.prepare>;
    /** 本模型字段ValueFun中的明确来源引用变更；不修改输出名称。 */
    fieldExpressionChanges: ReturnType<typeof LowcodeDataSpaceFieldMigration.prepare>;
}

